sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoSelecionado = "";
  $scope.latestYear = null;
  $scope.dadosVisiveis = null;
  $scope.isFading = false;
  var currentAngle = 0;
  var animationFrameId = null;

  function loadChartJs() {
    return new Promise(function(resolve) {
      if (window.Chart) {
        resolve();
        return;
      }
      var script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/npm/chart.js';
      script.onload = resolve;
      document.head.appendChild(script);
    });
  }

  function mapValueToAngle(realValue) {
    var limitedValue = Math.max(0, Math.min(realValue, 100));
    var relativeAngleDeg = (limitedValue / 100) * 180;
    return (relativeAngleDeg * Math.PI) / 180;
  }

  function syncPointerCanvasSize() {
    var chartCanvas = document.getElementById('gaugeChart');
    var pointerCanvas = document.getElementById('gaugePointer');
    if (!chartCanvas || !pointerCanvas) return;
    pointerCanvas.width = chartCanvas.offsetWidth;
    pointerCanvas.height = chartCanvas.offsetHeight;
  }

  function drawPointerAtAngle(angle, percentual) {
    var canvas = document.getElementById('gaugePointer');
    var ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    var width = canvas.width;
    var height = canvas.height;
    var cx = width / 2;
    var cy = height;
    var length = height * 0.75;

    var tipX = cx + length * Math.cos(Math.PI - angle);
    var tipY = cy - length * Math.sin(Math.PI - angle);

    ctx.beginPath();
    ctx.moveTo(cx, cy);
    ctx.lineTo(tipX, tipY);
    ctx.strokeStyle = '#333';
    ctx.lineWidth = 3;
    ctx.stroke();

    var arrowHeadLength = height * 0.08;
    var arrowHeadWidth = height * 0.05;

    var ux = Math.cos(Math.PI - angle);
    var uy = -Math.sin(Math.PI - angle);

    var baseX = tipX - arrowHeadLength * ux;
    var baseY = tipY - arrowHeadLength * uy;

    var leftX = baseX + (arrowHeadWidth / 2) * uy;
    var leftY = baseY + (arrowHeadWidth / 2) * -ux;

    var rightX = baseX - (arrowHeadWidth / 2) * uy;
    var rightY = baseY - (arrowHeadWidth / 2) * -ux;

    ctx.beginPath();
    ctx.moveTo(tipX, tipY);
    ctx.lineTo(leftX, leftY);
    ctx.lineTo(rightX, rightY);
    ctx.closePath();
    ctx.fillStyle = '#333';
    ctx.fill();

    ctx.beginPath();
    ctx.arc(cx, cy, 5, 0, 2 * Math.PI);
    ctx.fill();

    // Percentual na ponta da seta
    if (percentual !== undefined && percentual !== null) {
      var textOffset = height * 0.1;
      var textX = tipX + ux * textOffset;
      var textY = tipY + uy * textOffset;

      ctx.font = 'bold 18px Arial';
      ctx.fillStyle = '#333';
      ctx.textAlign = 'right';
      ctx.textBaseline = 'down';
      ctx.fillText(percentual.toFixed(1) + '%', textX, textY);
    }

    // DESENHA APENAS 0% E 60% NA ESCALA
    drawScale();
  }

  function animatePointer(toAngle, percentual) {
    if (animationFrameId) cancelAnimationFrame(animationFrameId);

    var duration = 600;
    var startAngle = currentAngle;
    var delta = toAngle - startAngle;
    var startTime = performance.now();

    function step(now) {
      var elapsed = now - startTime;
      var progress = Math.min(elapsed / duration, 1);
      currentAngle = startAngle + delta * (1 - Math.pow(1 - progress, 3));
      drawPointerAtAngle(currentAngle, percentual);
      if (progress < 1) {
        animationFrameId = requestAnimationFrame(step);
      }
    }

    requestAnimationFrame(step);
  }

function renderGauge(comprometimento) {
    var ctx = document.getElementById('gaugeChart').getContext('2d');

    if (window.myGaugeChart) {
        window.myGaugeChart.destroy();
    }

    // Criando o degradê suave e contínuo até 100%
    var gradient = ctx.createLinearGradient(0, 0, 300, 0);

    // Verde puro até 50%
    gradient.addColorStop(0, '#8BC34A');     // Verde no início (0%)
    gradient.addColorStop(0.50, '#8BC34A');  // Verde até 50%

    // Transição suave verde → amarelo (50% a 53%)
    gradient.addColorStop(0.50, '#8BC34A');  // Verde
    gradient.addColorStop(0.515, '#9BCD4F'); // Verde-amarelo
    gradient.addColorStop(0.53, '#FFEB3B');  // Amarelo

    // Amarelo puro (53% a 55%)
    gradient.addColorStop(0.53, '#FFEB3B');  // Amarelo
    gradient.addColorStop(0.55, '#FFEB3B');  // Amarelo

    // Transição suave amarelo → laranja (55% a 57%)
    gradient.addColorStop(0.55, '#FFEB3B');  // Amarelo
    gradient.addColorStop(0.56, '#FFC107');  // Amarelo-alaranjado
    gradient.addColorStop(0.57, '#FF9800');  // Laranja

    // Transição suave laranja → vermelho (57% a 58%)
    gradient.addColorStop(0.57, '#FF9800');  // Laranja
    gradient.addColorStop(0.575, '#FF5722'); // Laranja-avermelhado
    gradient.addColorStop(0.58, '#F44336');  // Vermelho

    // Vermelho puro (58% a 65%)
    gradient.addColorStop(0.58, '#F44336');  // Vermelho
    gradient.addColorStop(0.65, '#F44336');  // Vermelho

    // Transição suave vermelho → vermelho escuro (65% a 100%)
    gradient.addColorStop(0.65, '#F44336');  // Vermelho
    gradient.addColorStop(0.75, '#D32F2F');  // Vermelho médio
    gradient.addColorStop(0.85, '#C62828');  // Vermelho escuro
    gradient.addColorStop(1, '#B71C1C');     // Vermelho muito escuro

    window.myGaugeChart = new Chart(ctx, {
        type: 'doughnut',
        data: {
            labels: ['Escala 0-100%'],
            datasets: [{
                data: [100], // 100% para cobrir toda a escala
                backgroundColor: [gradient],
                borderWidth: 0,
                circumference: 180,
                rotation: 270,
                cutout: '70%'
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { 
                    display: false
                },
                tooltip: {
                    enabled: false
                }
            }
        }
    });

    $timeout(function() {
        syncPointerCanvasSize();
        var targetAngle = mapValueToAngle(comprometimento);
        animatePointer(targetAngle, comprometimento);
    }, 300);
}

  // FUNÇÃO CORRIGIDA: Desenha 0% e 100% nas posições corretas
  function drawScale() {
    var canvas = document.getElementById('gaugePointer');
    if (!canvas) return;

    var ctx = canvas.getContext('2d');
    var width = canvas.width;
    var height = canvas.height;
    var cx = width / 2;

    ctx.font = 'bold 16px Arial';
    ctx.fillStyle = '#333';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';

    // Usa 40% da largura total para cada lado a partir do centro
    var offset = width * 0.40;

    // 0% - alinhado com o início do segmento verde (esquerda)
    ctx.fillText('0%', cx - offset, height - 25);

    // 100% - alinhado com o fim do segmento vermelho (direita)
    ctx.fillText('100%', cx + offset, height - 25);
}

  function atualizarDados(ano) {
    $scope.isFading = true;

    $timeout(function() {
      if (!ano) {
        $scope.latestYear = null;
        $scope.dadosVisiveis = null;
        if (window.myGaugeChart) {
          window.myGaugeChart.destroy();
          window.myGaugeChart = null;
        }
        var ctxPointer = document.getElementById('gaugePointer');
        if (ctxPointer) {
          var ctx = ctxPointer.getContext('2d');
          ctx.clearRect(0, 0, ctxPointer.width, ctxPointer.height);
        }
      } else {
        spUtil.get('widget_limite_com_despesas_semidonut', { filtro_ano: ano }).then(function(response) {
          if (response.data && response.data.dados && response.data.dados.length > 0) {
            $scope.dadosVisiveis = response.data.dados[0];
            $scope.latestYear = ano;
            renderGauge($scope.dadosVisiveis.comprometimento);

            $timeout(function() {
              syncPointerCanvasSize();
              drawScale();
              var targetAngle = mapValueToAngle($scope.dadosVisiveis.comprometimento);
              drawPointerAtAngle(targetAngle, $scope.dadosVisiveis.comprometimento);
            }, 300);
          } else {
            $scope.dadosVisiveis = null;
            $scope.latestYear = null;
            if (window.myGaugeChart) {
              window.myGaugeChart.destroy();
              window.myGaugeChart = null;
            }
            var ctxPointer = document.getElementById('gaugePointer');
            if (ctxPointer) {
              var ctx = ctxPointer.getContext('2d');
              ctx.clearRect(0, 0, ctxPointer.width, ctxPointer.height);
            }
          }
        });
      }

      $scope.isFading = false;
    }, 500);
  }

  $scope.anoChanged = function() {
    if ($scope.anoSelecionado && ($scope.anoSelecionado < 2000 || $scope.anoSelecionado > new Date().getFullYear())) {
      console.warn("Ano fora do intervalo permitido.");
      return;
    }
    $rootScope.$broadcast('anoSelecionado', $scope.anoSelecionado);
  };

  loadChartJs().then(function() {
    $rootScope.$on('anoSelecionado', function(evt, ano) {
      $scope.anoSelecionado = ano;
      atualizarDados(ano);
    });

    window.addEventListener('resize', function() {
      if ($scope.dadosVisiveis && $scope.dadosVisiveis.comprometimento != null) {
        syncPointerCanvasSize();
        drawScale();
        var angle = mapValueToAngle($scope.dadosVisiveis.comprometimento);
        drawPointerAtAngle(angle, $scope.dadosVisiveis.comprometimento);
      }
    });
  });
}

sp_widget.css:
.report-widget {
  border-radius: 12px;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
  background-color: #fff;
  margin-top: 24px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: 'Roboto Flex', sans-serif;
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
}

.report-widget.panel.fade-out {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
}

.panel-heading {
  background-color: #e0e0e0;
  padding: 12px 16px;
  border-bottom: 1px solid #ccc;
  border-top-left-radius: 12px;
  border-top-right-radius: 12px;
}

.panel-title {
  margin: 0;
  font-size: 18px;
  color: #333;
  text-align: center;
  font-size: 1.2em;
}

.panel-body {
  padding: 16px;
  flex: 1;
  width: 100%;
  text-align: center;
  font-size: 1.2em;
}

/* Container principal do gráfico */
.chart-container-wrapper {
  position: relative;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

.chart-container {
  position: relative;
  width: 100%;
  max-width: 800px;
  height: 250px;
  margin: 0 auto;
}

canvas {
  display: block;
  margin: 0 auto;
  max-width: 100%;
  height: auto;
}

/* Legenda melhorada */
.legenda-container {
  width: 100%;
  display: flex;
  justify-content: center;
}

.legenda {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px;
  font-family: 'Roboto Flex', sans-serif;
  font-size: 14px;
  max-width: 800px;
  margin: 0 auto;
}

.legenda-item {
  display: flex;
  align-items: center;
  margin-bottom: 8px;
}

.legenda-color {
  width: 16px;
  height: 16px;
  margin-right: 8px;
  border-radius: 3px;
  flex-shrink: 0;
}

.legenda-text {
  white-space: nowrap;
  font-size: 12px;
}

/* Comprometimento */
.comprometimento {
  text-align: center;
  margin-top: 25px;
  padding: 10px;
  background-color: #f8f9fa;
  border-radius: 6px;
  font-size: 16px;
}

/* Mensagem sem dado */
.mensagem {
  opacity: 0;
  visibility: hidden;
  transform: translateY(20px);
  transition: opacity 0.5s ease-in-out, visibility 0.5s ease-in-out, transform 0.5s ease-in-out;
  height: 0;
  overflow: hidden;
}

.mensagem.show {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
  height: auto;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  .report-widget {
    margin-top: 1rem;
  }

  .panel-title {
    font-size: 1.1rem;
  }

  .panel-body {
    padding: 12px;
  }

  .chart-container {
    height: 180px;
  }

  .legenda {
    flex-direction: column;
    align-items: flex-start;
    gap: 8px;
    font-size: 12px;
  }

  .legenda-item {
    margin-bottom: 5px;
  }

  .legenda-text {
    font-size: 11px;
  }

  .comprometimento {
    margin-top: 20px;
    font-size: 14px;
  }
}

/* Tablets (768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  .report-widget {
    margin-top: 1.5rem;
  }

  .panel-title {
    font-size: 1.3rem;
  }

  .chart-container {
    height: 220px;
  }

  .legenda {
    gap: 20px;
  }

  .legenda-text {
    font-size: 13px;
  }
}

/* Laptops e Telas Maiores (1024px em diante) */
@media (min-width: 1024px) {
  .report-widget {
    margin-top: 24px;
  }

  .panel-title {
    font-size: 1.4rem;
  }

  .chart-container {
    height: 250px;
  }

sp_widget.script:
(function() {
  var anoFiltrado = (typeof input !== 'undefined' && input.filtro_ano) ? input.filtro_ano : '';
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');

  if (anoFiltrado) {
    gr.addQuery('u_ano', anoFiltrado);
  }

  gr.orderByDesc('u_ano');
  gr.query();

  var dados = [];
  while (gr.next()) {
    dados.push({
      ano: gr.getValue('u_ano'),
      comprometimento: parseFloat(gr.getValue('u_comprometimento_rcl')) || 0
    });
  }

	//gs.addInfoMessage(JSON.stringify(dados));

  data.dados = dados;
})();
